ALTER TABLE Campaign ADD COLUMN platform VARCHAR(191) NULL, ADD COLUMN externalCampaignId VARCHAR(191) NULL, ADD COLUMN lastSyncedAt DATETIME(3) NULL; CREATE UNIQUE INDEX Campaign_platform_externalCampaignId_key ON Campaign(platform, externalCampaignId); CREATE TABLE CampaignMetricSnapshot ( id VARCHAR(191) NOT NULL, campaignId VARCHAR(191) NOT NULL, date DATETIME(3) NOT NULL, impressions INTEGER NOT NULL DEFAULT 0, clicks INTEGER NOT NULL DEFAULT 0, spend DECIMAL(10, 2) NOT NULL DEFAULT 0, conversions DECIMAL(10, 2) NULL, conversionValue DECIMAL(10, 2) NULL, currencyCode VARCHAR(191) NOT NULL DEFAULT 'USD', createdAt DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE INDEX CampaignMetricSnapshot_campaignId_date_key(campaignId, date), PRIMARY KEY (id) ) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci; ALTER TABLE CampaignMetricSnapshot ADD CONSTRAINT CampaignMetricSnapshot_campaignId_fkey FOREIGN KEY (campaignId) REFERENCES Campaign(id) ON DELETE CASCADE ON UPDATE CASCADE;
